CREATE TABLE IF NOT EXISTS economic_operational_readiness_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid, run_key text NOT NULL, status text NOT NULL DEFAULT 'running', checks jsonb NOT NULL DEFAULT '[]'::jsonb, public_exposure boolean NOT NULL DEFAULT false, production_data_affected boolean NOT NULL DEFAULT false, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);